+#[derive(Debug, Clone, Copy)]
+pub enum PlumbingDiff {
+    /// `git diff-tree`: tree against tree.
+    Tree,
+    /// `git diff-index`: tree against the index or working tree.
+    Index,
+    /// `git diff-files`: index against working tree.
+    Files,
+}
