+    pub fn args<'a>(self, args: &[&'a str]) -> Vec<&'a str> {
+        let command = match self {
+            Self::Tree => "diff-tree",
+            Self::Index => "diff-index",
+            Self::Files => "diff-files",
+        };
+        let mut all = vec![command, "--ignore-submodules=none"];
+        all.extend_from_slice(args);
+        all
+    }
