+pub fn handle_logs_profile(file: Option<PathBuf>, format: SwitchFormat) -> anyhow::Result<()> {
+    let (input, source) = match file {
+        Some(ref p) if p.as_os_str() == "-" => {
+            let mut buf = String::new();
