+    let profile = worktrunk::trace::Profile::from_entries(&entries);
+
+    if format == SwitchFormat::Json {
+        println!("{}", serde_json::to_string_pretty(&profile)?);
+    } else {
+        show_help_in_pager(&profile.render_text(&source), true);
+    }
