+    let script = format!(
+        r#"
+$env:WORKTRUNK_BIN = '{mock_bin_escaped}'
+{wrapper}
+wt remove -D test --force
+"#
+    );
+
+    let output = Command::new("pwsh")
+        .args(["-NoProfile", "-NonInteractive", "-Command", &script])
+        .output()
+        .expect("Failed to run pwsh");
+
