+        .unwrap();
+
+    // Both files have identical diffs, so full = 2x sparse
+    assert_eq!(full_stats.added, 4, "full: inside/ + outside/ additions");
+    assert_eq!(full_stats.deleted, 2, "full: inside/ + outside/ deletions");
+}

