+/// Check if string starts with a foreground color escape: `\x1b[30-37m` or `\x1b[90-97m`.
+fn starts_with_fg_color(s: &str) -> bool {
+    let b = s.as_bytes();
+    b.len() >= 5
+        && b[0] == b'\x1b'
+        && b[1] == b'['
+        && (b[2] == b'3' || b[2] == b'9')
+        && b[3] >= b'0'
+        && b[3] <= b'7'
+        && b[4] == b'm'
+}
