+        struct RestorePerms<'a>(&'a std::path::Path);
+        impl Drop for RestorePerms<'_> {
+            fn drop(&mut self) {
+                let mut perms = std::fs::metadata(self.0).unwrap().permissions();
+                perms.set_mode(0o644);
+                let _ = std::fs::set_permissions(self.0, perms);
+            }
