+/// Internal implementation with optional home override.
+fn exec_in_pty_impl(
+    command: &str,
+    args: &[&str],
+    working_dir: &Path,
+    env_vars: &[(String, String)],
+    input: &str,
+    home_dir: Option<&Path>,
