+                .iter()
+                .map(|f| f.name.as_deref().unwrap_or("(unnamed)"))
+                .collect();
+            format!(
+                "{} commands failed: {}",
+                all_failures.len(),
+                names.join(", ")
+            )
+        };
+
+        return Err(WorktrunkError::HookCommandFailed {
+            hook_type,
+            command_name: first.name.clone(),
+            error: error_msg,
+            exit_code: first.exit_code,
         }
         .into());
     }
